// Simulasi konsep: sinyal metrik → diringkas per interval waktu (misal per menit)
// Data format: { t: detikSejakMulai, cpu: nilaiCPU }
const signals = [ { t: 0, cpu: 10 }, { t: 20, cpu: 12 }, { t: 40, cpu: 14 }, { t: 60, cpu: 30 }, { t: 70, cpu: 28 }, { t: 90, cpu: 26 } ];

const intervalSec = 60; // 1 menit
const buckets = new Map();

for (const s of signals) {
  const bucketIndex = Math.floor(s.t / intervalSec);
  if (!buckets.has(bucketIndex)) buckets.set(bucketIndex, []);
  buckets.get(bucketIndex).push(s.cpu);
}

const metrics = Array.from(buckets.entries())
  .sort((a, b) => a[0] - b[0])
  .map(([idx, values]) => {
    const avg = values.reduce((acc, v) => acc + v, 0) / values.length;
    return { minute: idx + 1, avgCpu: avg };
  });

console.log('Metrik CPU rata-rata per menit:', metrics);

// Challenge: ubah intervalSec jadi 30 detik lalu lihat metriknya berubah.

// Simulasi konsep: Cloud Logging punya kategori utama (audit, agen, jaringan, layanan)
// Kita buat aturan sederhana berdasarkan field eventType.

const logs = [
  { id: 1, eventType: 'AUDIT', message: 'Admin mengubah setting', user: 'alice' },
  { id: 2, eventType: 'AGENT', message: 'Fluentd mengirim log instance', vm: 'compute-1' },
  { id: 3, eventType: 'VPC_FLOW', message: 'Sample alur jaringan VPC', src: '10.0.0.2', dst: '10.0.0.8' },
  { id: 4, eventType: 'SERVICE', message: 'Container mencatat stdout error', service: 'cloud-run-app' }
];

function categorizeLog(log) {
  const t = log.eventType;
  if (t === 'AUDIT') return 'log audit';
  if (t === 'AGENT') return 'log agen';
  if (t === 'VPC_FLOW' || t === 'FIREWALL' || t === 'NAT') return 'log jaringan';
  return 'log layanan';
}

const summarized = logs.map(l => ({ id: l.id, category: categorizeLog(l), message: l.message }));
console.log('Ringkasan kategori log:', summarized);

